create table public.events(id uuid primary key default gen_random_uuid(),organizer_id uuid not null references public.profiles(id) on delete restrict,campus_id uuid not null references public.campuses(id) on delete restrict,title text not null,description text not null default '',venue text not null,starts_at timestamptz not null,ends_at timestamptz not null,capacity integer,registration_deadline timestamptz,visibility text not null default 'campus',status text not null default 'draft',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),deleted_at timestamptz,constraint events_dates check(ends_at>starts_at),constraint events_capacity check(capacity is null or capacity>0));
create table public.event_media(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,media_asset_id uuid not null references public.media_assets(id) on delete restrict,position smallint not null,created_at timestamptz not null default timezone('utc',now()),unique(event_id,position));
create table public.event_registrations(event_id uuid not null references public.events(id) on delete restrict,user_id uuid not null references public.profiles(id) on delete restrict,status text not null default 'registered',waitlist_position integer,checked_in_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),primary key(event_id,user_id));
create table public.jobs(id uuid primary key default gen_random_uuid(),poster_id uuid not null references public.profiles(id) on delete restrict,campus_id uuid not null references public.campuses(id) on delete restrict,employer text not null,title text not null,description text not null,location text,employment_type text not null,deadline timestamptz,status text not null default 'draft',visibility text not null default 'campus',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),deleted_at timestamptz);
create table public.job_skills(job_id uuid not null references public.jobs(id) on delete cascade,skill_id uuid not null references public.skills(id) on delete restrict,requirement_level smallint,created_at timestamptz not null default timezone('utc',now()),primary key(job_id,skill_id));
create table public.job_applications(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs(id) on delete restrict,applicant_id uuid not null references public.profiles(id) on delete restrict,resume_asset_id uuid references public.media_assets(id) on delete restrict,cover_letter text not null default '',status text not null default 'submitted',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(job_id,applicant_id));
create table public.job_application_documents(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.job_applications(id) on delete cascade,media_asset_id uuid not null references public.media_assets(id) on delete restrict,document_type text not null,created_at timestamptz not null default timezone('utc',now()),unique(application_id,media_asset_id));
create index events_time_idx on public.events(campus_id,starts_at); create index registrations_user_idx on public.event_registrations(user_id,status); create index jobs_feed_idx on public.jobs(campus_id,status,created_at desc) where deleted_at is null; create index applications_applicant_idx on public.job_applications(applicant_id,status);
alter table public.events enable row level security;alter table public.event_media enable row level security;alter table public.event_registrations enable row level security;alter table public.jobs enable row level security;alter table public.job_skills enable row level security;alter table public.job_applications enable row level security;alter table public.job_application_documents enable row level security;
create policy events_read on public.events for select to authenticated using(status='published' or organizer_id=auth.uid() or public.has_permission('events.manage',campus_id)); create policy events_manage on public.events for all to authenticated using(organizer_id=auth.uid() or public.has_permission('events.manage',campus_id)) with check(organizer_id=auth.uid() or public.has_permission('events.manage',campus_id)); create policy event_media_read on public.event_media for select to authenticated using(true); create policy event_media_owner on public.event_media for all to authenticated using(exists(select 1 from public.events e where e.id=event_id and e.organizer_id=auth.uid())) with check(exists(select 1 from public.events e where e.id=event_id and e.organizer_id=auth.uid())); create policy registrations_read on public.event_registrations for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and e.organizer_id=auth.uid())); create policy registrations_insert on public.event_registrations for insert to authenticated with check(user_id=auth.uid()); create policy registrations_update on public.event_registrations for update to authenticated using(user_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and e.organizer_id=auth.uid())) with check(user_id=auth.uid() or exists(select 1 from public.events e where e.id=event_id and e.organizer_id=auth.uid())); create policy jobs_read on public.jobs for select to authenticated using(status='published' or poster_id=auth.uid() or public.has_permission('jobs.manage',campus_id)); create policy jobs_manage on public.jobs for all to authenticated using(poster_id=auth.uid() or public.has_permission('jobs.manage',campus_id)) with check(poster_id=auth.uid() or public.has_permission('jobs.manage',campus_id)); create policy job_skills_read on public.job_skills for select to authenticated using(true); create policy job_skills_owner on public.job_skills for all to authenticated using(exists(select 1 from public.jobs j where j.id=job_id and j.poster_id=auth.uid())) with check(exists(select 1 from public.jobs j where j.id=job_id and j.poster_id=auth.uid())); create policy applications_read on public.job_applications for select to authenticated using(applicant_id=auth.uid() or exists(select 1 from public.jobs j where j.id=job_id and j.poster_id=auth.uid())); create policy applications_insert on public.job_applications for insert to authenticated with check(applicant_id=auth.uid()); create policy applications_update on public.job_applications for update to authenticated using(applicant_id=auth.uid() or exists(select 1 from public.jobs j where j.id=job_id and j.poster_id=auth.uid())) with check(applicant_id=auth.uid() or exists(select 1 from public.jobs j where j.id=job_id and j.poster_id=auth.uid())); create policy application_documents_read on public.job_application_documents for select to authenticated using(exists(select 1 from public.job_applications a where a.id=application_id and a.applicant_id=auth.uid())); create policy application_documents_owner on public.job_application_documents for all to authenticated using(exists(select 1 from public.job_applications a where a.id=application_id and a.applicant_id=auth.uid())) with check(exists(select 1 from public.job_applications a where a.id=application_id and a.applicant_id=auth.uid()));
